def amicable_numbers_sum(n):
    def sum_divisors(num):
        total = 1 if num > 1 else 0
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:
                    total += num // i
        return total

    amicable_pairs = set()

    for number in range(2, n + 1):
        d_sum = sum_divisors(number)

        # Check if the pair exists within bounds and is not a perfect number or part of an already found chain that isn't amicable
        partner_d_sum = sum_divisors(d_sum)

        if partner_d_sum == number:
            continue

        if d_sum != 1 and partner_d_sum > n:
            break

        # Check for mutual relationship within bounds
        if d_sum <= n and sum_divisors(partner_d_sum) == number:
            amicable_pairs.add(min(number, d_sum))

    return sum(amicable_pairs)

