def find_solution(a, b, n):
    if a == 0:
        return None if b != 0 and n % b else (None, n // b)
    if b == 0:
        return None if a != 0 and n % a else (n // a, None)

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    g, x0, y0 = extended_gcd(a, b)

    if n % g != 0:
        return None

    scale = n // g
    x = (x0 * scale) % b
    y = ((n - a * x) // b)

    return int(x), int(y)

