        float(s)
    except ValueError:
        return False

    parts = s.split('.')

    if len(parts) != 2:
        return False

    integer_part, decimal_part = parts[0], parts[1]

    if not integer_part or not decimal_part:
        return False

    for char in integer_part + decimal_part:
        if not (char.isdigit() or char == '.'):
            return False

    if len(decimal_part) != 2:
        return False

    try:
        float(s)
    except ValueError:
        return False

