    for item in t:
        if isinstance(item, tuple) and len(item) > 0:
            inner_result = remove_nested(item)
            if any(isinstance(x, tuple) for x in inner_result):
                new_inner = [x for x in inner_result if not isinstance(x, tuple)]
                result.append(tuple(new_inner))
            else:
                result.extend(inner_result)
        elif item is None or len(tuple(item)) == 0:
            continue
        else:
            result.append(item)
    return tuple(result)

def last(arr, x):
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == x:
            # Move to the right half to find the last occurrence
            left = mid + 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return left - 1

